<?php $rows=db()->query('SELECT department, business_unit, SUM(po_committed_amount) committed, SUM(released_amount) released FROM commitments GROUP BY department,business_unit')->fetchAll(); ?>
<div class="card p-3"><h5>Budget / Cost Summary</h5><table class="table table-sm"><tr><th>Department</th><th>Business Unit</th><th>Committed</th><th>Released</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['department'])?></td><td><?=e($r['business_unit'])?></td><td><?=number_format((float)$r['committed'],2)?></td><td><?=number_format((float)$r['released'],2)?></td></tr><?php endforeach;?></table></div>
